## 3. CODIFICAÇÃO EM JAVA

```java
import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String line = br.readLine();
        if (line == null) return;

        int n = Integer.parseInt(line.trim());

        long bestCents = -1;
        long bestG = 1;

        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());

            long cents = parseCents(st.nextToken());
            long g = Long.parseLong(st.nextToken());

            // Compara cents1 / G1 < cents2 / G2
            if (bestCents == -1 || cents * bestG < bestCents * g) {
                bestCents = cents;
                bestG = g;
            }
        }

        // valor = bestCents * 10 / bestG
        // valor * 100 = bestCents * 1000 / bestG
        long num = bestCents * 1000L;
        long den = bestG;

        // Arredondamento half-up para inteiro
        long q = (num + den / 2) / den;

        System.out.printf("%d.%02d%n", q / 100, q % 100);
    }

    // Converte "P" para centavos de Bit.
    // Ex.: "3.0" -> 300, "25.72" -> 2572, "1000.00" -> 100000
    private static long parseCents(String s) {
        int dot = s.indexOf('.');

        if (dot == -1) {
            return Long.parseLong(s) * 100L;
        }

        String intPart = s.substring(0, dot);
        String frac = s.substring(dot + 1);

        if (intPart.isEmpty()) intPart = "0";

        long integer = Long.parseLong(intPart);

        if (frac.length() == 0) {
            return integer * 100L;
        } else if (frac.length() == 1) {
            frac = frac + "0";
        } else if (frac.length() > 2) {
            frac = frac.substring(0, 2);
        }

        return integer * 100L + Long.parseLong(frac);
    }
}
```

